S={(0,1):4,(1,1):4,(1,2):2,(2,0):3,(2,2):2}; target={(0,0),(1,1),(1,2),(2,0),(2,1)}
def transforms(d):
 out=[]
 for k in range(4):
  x={p:v for p,v in d.items()}; n=3
  for _ in range(k): x={(c,n-1-r):v for (r,c),v in x.items()}
  out.append((k,False,x))
  out.append((k,True,{(r,n-1-c):v for (r,c),v in x.items()}))
 return out
[(k,ref,set(d)==target,d) for k,ref,d in transforms(S)]
